import scala.collection.mutable.Map
// Define customer intents
object Intents extends Enumeration {
  type Intents = Value
  val GREETING, SEARCH_PRODUCT, BOOK_HOTEL, BOOK_FLIGHT = Value
}
// Define entities
case class Entity(name: String, value: String)
// Define state machine
case class State(name: String, transitions: Map[Intents.Value, State])
val initialState = State("initial", Map(
  Intents.GREETING -> State("greeting", Map(
    Intents.SEARCH_PRODUCT -> State("searchProduct", Map(
      Intents.BOOK_HOTEL -> State("bookHotel", Map()),
      Intents.BOOK_FLIGHT -> State("bookFlight", Map())
    )),
    Intents.BOOK_HOTEL -> State("bookHotel", Map()),
    Intents.BOOK_FLIGHT -> State("bookFlight", Map())
  )),
  Intents.SEARCH_PRODUCT -> State("searchProduct", Map(
    Intents.BOOK_HOTEL -> State("bookHotel", Map()),
    Intents.BOOK_FLIGHT -> State("bookFlight", Map())
  )),
  Intents.BOOK_HOTEL -> State("bookHotel", Map()),
  Intents.BOOK_FLIGHT -> State("bookFlight", Map())
))
// Define response generation
def generateResponse(intent: Intents.Value, entities: List[Entity]): String = {
  intent match {
    case Intents.GREETING => "Thanks for contacting us! How can I assist you today?"
    case Intents.SEARCH_PRODUCT => "Here are some products that match your search criteria."
    case Intents.BOOK_HOTEL => s"Great! Your hotel booking is confirmed for ${entities(0).value}. Your confirmation number is ${entities(1).value}."
    case Intents.BOOK_FLIGHT => s"Great! Your flight booking is confirmed for ${entities(0).value}. Your confirmation number is ${entities(1).value}."
  }
}
// Handle user input and extract entities
val userInput = "I want to book a hotel in Paris for next weekend"
val intent = Intents.BOOK_HOTEL
val entities = List(Entity("location", "Paris"), Entity("dateRange", "next weekend"))
// Manage conversation flow
var currentState = initialState
for (entity <- entities) {
  currentState = currentState.transitions.get(intent) match {
    case Some(state) => state.transitions.get(entity.name) match {
      case Some(state) => state
      case None => // Code to handle error
    }
    case None => // Code to handle error
  }
}
// Generate response
val response = generateResponse(currentState.name, entities)
```
This code demonstrates how the chatbot would handle a user's request to book a hotel in Paris for next weekend. The chatbot extracts the location and date range from the user's message, and then uses a state machine to manage the conversation flow. Finally, the chatbot generates a response based on the user's input and the current conversation state. The response in this case would be "Great! Your hotel booking is confirmed for Paris. Your confirmation number is next weekend."

