Here is an example of how to encrypt and decrypt data using AES in C#:
```csharp
using System;
using System.IO;
using System.Security.Cryptography;
public static class EncryptionHelper
{
    private static readonly byte[] Salt = new byte[] { 0x26, 0x19, 0x72, 0x2A, 0x5E, 0xD4, 0x33, 0x22 };
    private static readonly byte[] Key = new byte[] { 0x5E, 0x5C, 0x5D, 0x5A, 0x5B, 0x5F, 0x58, 0x59, 0x54, 0x55, 0x50, 0x51, 0x56, 0x57, 0x52, 0x53 };
    public static string Encrypt(string plainText)
    {
        byte[] encryptedData;
        using (var aes = Aes.Create())
        {
            aes.Key = Key;
            aes.GenerateIV();
            var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);
            using (var ms = new MemoryStream())
            {
                ms.Write(aes.IV, 0, aes.IV.Length);
                using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
                using (var sw = new StreamWriter(cs))
                {
                    sw.Write(plainText);
                }
                encryptedData = ms.ToArray();
            }
        }
        return Convert.ToBase64String(encryptedData);
    }
    public static string Decrypt(string cipherText)
    {
        byte[] cipherData = Convert.FromBase64String(cipherText);
        using (var aes = Aes.Create())
        {
            aes.Key = Key;
            byte[] iv = new byte[16];
            Buffer.BlockCopy(cipherData, 0, iv, 0, iv.Length);
            var decryptor = aes.CreateDecryptor(aes.Key, iv);
            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Write))
                {
                    cs.Write(cipherData, iv.Length, cipherData.Length - iv.Length);
                }
                return System.Text.Encoding.UTF8.GetString(ms.ToArray());
            }
        }
    }
}
```
In this example, we use a fixed key and salt for simplicity, but in a real-world scenario, you should use a more secure approach to generate these values.

