print("Water pollution impact: \(waterPollutionImpact)")
print("Soil pollution impact: \(soilPollutionImpact)")
```
This code defines a formula to calculate the impact of pollution based on the number of unique sources and effects for each category of pollution, and the total amount of data in that category. It then calculates the impact for each of the three primary categories of pollution and prints the results to the console.

How can I use C++ code to demonstrate the concept of dynamic programming in a practical manner?
Consider the following example code:
#include <iostream>
#include <vector>
using namespace std;
int fib(int n, vector<int>& memo) {
    if (memo[n] != -1) {
        return memo[n];
    }
    if (n == 0 || n == 1) {
        memo[n] = n;
    } else {
        memo[n] = fib(n-1, memo) + fib(n-2, memo);
    }
    return memo[n];
}
int main() {
    int n = 10;
    vector<int> memo(n+1, -1);
    cout << "Fibonacci sequence up to " << n << ":" << endl;
    for (int i = 0; i <= n; i++) {
        cout << fib(i, memo) << " ";
    }
    cout << endl;
    return 0;
}
