```c++
#include <iostream>
using namespace std;
// Function to print the folding instructions
void printInstructions(int n, bool alternate) {
    if (n == 0) {
        return;
    }
    if (alternate) {
        cout << "Fold the top right corner down to meet the bottom left corner." << endl;
        cout << "Fold the bottom right corner up to meet the top left corner." << endl;
    } else {
