        cout << "Fold the top left corner down to meet the center crease." << endl;
        cout << "Fold the bottom left corner up to meet the center crease." << endl;
    }
    printInstructions(n-1, !alternate);
}
int main() {
    int n;
    cout << "Enter the number of petals for the lotus flower (must be even): ";
    cin >> n;
    if (n % 2 != 0) {
        cout << "Error: Number of petals must be even." << endl;
