Here is the Java code I have for logistic regression:
public class LogisticRegression {
    private double[] weights;
    private double learningRate;
    private int numFeatures;
    public LogisticRegression(int numFeatures, double learningRate) {
        this.numFeatures = numFeatures;
        this.learningRate = learningRate;
        weights = new double[numFeatures];
    }
    public double predict(double[] features) {
        double logit = 0.0;
        for (int i = 0; i < numFeatures; i++) {
            logit += weights[i] * features[i];
        }
        return 1.0 / (1.0 + Math.exp(-logit));
    }
    public void train(double[][] features, int[] labels, int numIterations) {
        for (int iteration = 0; iteration < numIterations; iteration++) {
            for (int i = 0; i < features.length; i++) {
                double[] featureVector = features[i];
                int label = labels[i];
                double predicted = predict(featureVector);
                for (int j = 0; j < numFeatures; j++) {
                    double gradient = (label - predicted) * featureVector[j];
                    weights[j] += learningRate * gradient;
                }
            }
        }
    }
} 
