function pluralPossessive(n) {
  if (typeof n !== 'number' || isNaN(n)) {
    return "Invalid input";
  }
  var plural = "";
  if (n % 100 >= 11 && n % 100 <= 20) {
    plural = "th";
  } else if (n % 10 === 1) {
    plural = "st";
  } else if (n % 10 === 2) {
    plural = "nd";
  } else if (n % 10 === 3) {
    plural = "rd";
  } else {
    plural = "th";
  }
